(() => {
  const board = () => document.querySelector("#board");
  const save = () => {
    const c = board();
    if (!c) return;
    c.toBlob(blob => {
      if (!blob) return;
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "sketch.png";
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    }, "image/png");
  };
  morse.watch('div[aria-label="Tools"]', tools => {
    if (tools.querySelector(":scope > .morse-save")) return;
    const btn = morse.el("button", {
      class: "morse-save",
      "aria-label": "Save PNG",
      title: "Save as PNG",
      style: "width:38px;height:38px;border:0;border-radius:8px;background:transparent;cursor:pointer;font-size:18px;color:currentColor;",
      text: "💾",
      on: { click: save }
    });
    tools.appendChild(btn);
  });
})();

