let dir = 1;
morse.watch("div.sc > table > thead > tr > th.am", th => {
  morse.on(th, "click", () => {
    dir = -dir;
    const idx = [...th.parentElement.children].indexOf(th);
    const tbody = th.closest("table").tBodies[0];
    const val = r => parseFloat((r.cells[idx]?.textContent || "").replace(/[^0-9.\-]/g, "")) || 0;
    const rows = [...tbody.rows].sort((a, b) => (val(a) - val(b)) * dir);
    tbody.append(...rows);
  });
});

