morse.watch("div.sc > table > thead > tr > th.am", th => {
  const table = th.closest("table");
  const idx = [...th.parentElement.children].indexOf(th);
  const num = td => parseFloat((td.textContent || "").replace(/[^0-9.\-]/g, "")) || 0;
  morse.on(th, "click", () => {
    const dir = th.dataset.sort === "desc" ? "asc" : "desc";
    th.dataset.sort = dir;
    const body = table.tBodies[0];
    const rows = [...body.rows];
    rows.sort((a, b) => {
      const d = num(a.cells[idx]) - num(b.cells[idx]);
      return dir === "asc" ? d : -d;
    });
    rows.forEach(r => body.appendChild(r));
  });
});

