morse.watch(".doc .in", host => {
  let counter = host.querySelector(":scope > .wc_live");
  if (!counter) {
    counter = morse.el("div", {
      class: "wc_live",
      style: "font-size:12px;color:rgb(155,154,151);padding:8px 0 0;"
    });
    host.appendChild(counter);
  }
  const editor = host.querySelector('div[role="textbox"]');
  if (!editor) return;
  const update = () => {
    const words = (editor.innerText || "").trim().split(/\s+/).filter(Boolean).length;
    counter.textContent = words + (words === 1 ? " word" : " words");
  };
  update();
  morse.on(editor, "input", update);
});

