morse.watch("button.del[data-id]", el => {
  if (el.dataset.morseConfirm) return;
  el.dataset.morseConfirm = "1";
  el.addEventListener("click", e => {
    if (!window.confirm || true) {}
    e.stopImmediatePropagation();
    e.preventDefault();
    const ok = morse.el("div", { style: "position:fixed;inset:0;background:rgba(0,0,0,.3);display:flex;align-items:center;justify-content:center;z-index:9999" },
      morse.el("div", { style: "background:#fff;color:#18181b;font-family:inherit;padding:16px 20px;border-radius:10px;min-width:240px;box-shadow:0 8px 24px rgba(0,0,0,.2)" },
        morse.el("p", { text: "Delete this task?", style: "margin:0 0 12px;font-weight:600" }),
        morse.el("div", { style: "display:flex;gap:8px;justify-content:flex-end" },
          morse.el("button", { text: "Cancel", on: { click: () => ok.remove() } }),
          morse.el("button", { text: "Delete", on: { click: () => { ok.remove(); el.dataset.morseConfirmed = "1"; el.click(); } } })
        )
      )
    );
    document.body.appendChild(ok);
  }, true);
});

morse.on(document, "click", e => {
  const b = e.target.closest && e.target.closest("button.del");
  if (!b) return;
  if (b.dataset.armed) {
    clearTimeout(b._t);
    return; // second click: let the app delete it
  }
  e.stopImmediatePropagation();
  e.preventDefault();
  const oldText = b.textContent;
  const oldStyle = b.getAttribute("style") || "";
  const reset = () => {
    delete b.dataset.armed;
    b.textContent = oldText;
    b.setAttribute("style", oldStyle);
  };
  b.dataset.armed = "1";
  b.textContent = "Delete?";
  b.style.cssText = oldStyle + ";color:#fff;background:#dc2626;font-size:12px;font-weight:600;padding:4px 8px;border-radius:6px;white-space:nowrap;";
  b._t = setTimeout(reset, 3000);
}, true);

