morse.on(document, "click", e => {
  const btn = e.target.closest && e.target.closest(".card .del");
  if (!btn) return;
  if (btn.dataset.ok) { delete btn.dataset.ok; return; }
  e.stopPropagation();
  e.preventDefault();
